CREATE TABLE routes (route_id BIGINT PRIMARY KEY, route_name TEXT NOT NULL, service_level TEXT, base_fee NUMERIC(12,2), enabled BOOLEAN NOT NULL);
CREATE TABLE shipments (shipment_id BIGINT PRIMARY KEY, shipper_id BIGINT NOT NULL REFERENCES shippers(shipper_id), route_id BIGINT NOT NULL REFERENCES routes(route_id), shipped_on DATE NOT NULL, package_count INTEGER NOT NULL, shipping_cost NUMERIC(12,2), shipment_status TEXT NOT NULL);
CREATE TABLE claims (claim_id BIGINT PRIMARY KEY, shipper_id BIGINT NOT NULL REFERENCES shippers(shipper_id), filed_on DATE NOT NULL, status TEXT NOT NULL);

